//! Minimal persistent-vector implementation matching the semantics of
//! `immer::vector<T>` as used by the original C++ program:
//! `push_back` returns a new vector, leaving the receiver unchanged.

#[derive(Clone, Default)]
pub struct Vector<T: Clone> {
    data: Vec<T>,
}

impl<T: Clone> Vector<T> {
    pub fn new() -> Self {
        Vector { data: Vec::new() }
    }

    pub fn push_back(&self, value: T) -> Self {
        let mut data = self.data.clone();
        data.push(value);
        Vector { data }
    }

    pub fn size(&self) -> usize {
        self.data.len()
    }
}

